window.__saMergeCourse({id:'al-biology-9700', board:'alevel', title:'Biology (9700)', urdu:'', class:'A Level', icon:'🧬', desc:'Cambridge A Level Biology 9700 — full AS & A2 syllabus with lessons and quizzes.', chapters:[
  {id:'al-bio-t1', title:'Cell structure (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t1-l1', title:'Microscopy: magnification and resolution', html:'<h3>Microscopy: magnification and resolution</h3><p><strong>Magnification</strong> = image size / actual size. <strong>Resolution</strong> = minimum distance apart two objects can be to be seen separately. Light microscopes: resolution ~200 nm (limited by wavelength of light); electron microscopes: ~0.1–1 nm.</p><p><strong>TEM</strong> (transmission): electrons pass through ultra-thin sections — high resolution, 2D black-and-white images, specimens dead (vacuum). <strong>SEM</strong> (scanning): electrons bounce off surfaces — 3D surface images, lower resolution than TEM.</p><p>Worked example: a micrograph shows a chloroplast 20 mm long at ×10 000. Actual size = 20 mm/10 000 = 2 μm. Always convert: measure in mm, convert to μm (×1000).</p>'},
    {id:'al-bio-t1-l2', title:'Organelles and their functions', html:'<h3>Organelles and their functions</h3><p><strong>Nucleus:</strong> DNA, controls cell activities; <strong>nucleolus</strong> makes ribosomes. <strong>Rough ER:</strong> protein synthesis/folding (ribosomes); <strong>smooth ER:</strong> lipid synthesis. <strong>Golgi:</strong> modifies, packages, secretes (vesicles). <strong>Mitochondrion:</strong> aerobic respiration (ATP). <strong>Chloroplast:</strong> photosynthesis (plants). <strong>Ribosome (80S/70S):</strong> protein synthesis. <strong>Lysosome:</strong> digestion (hydrolytic enzymes). <strong>Centrioles:</strong> organise spindle (animals).</p><p>Plant extras: <strong>cell wall</strong> (cellulose — support), <strong>large vacuole</strong> (turgor, storage), <strong>chloroplasts</strong>, <strong>plasmodesmata</strong>.</p><p>Adaptations: cells with high energy demand (muscle) have many mitochondria; secretory cells (goblet) have extensive RER/Golgi; root hair cells have large surface area, no chloroplasts.</p>'},
    {id:'al-bio-t1-l3', title:'Prokaryotic vs eukaryotic cells', html:'<h3>Prokaryotic vs eukaryotic cells</h3><p><strong>Prokaryotes</strong> (bacteria): no membrane-bound nucleus (circular DNA in nucleoid), 70S ribosomes, no mitochondria/chloroplasts, cell wall of peptidoglycan (murein), some have slime capsule, flagella, plasmids.</p><p><strong>Eukaryotes:</strong> true nucleus with linear DNA + histones, 80S ribosomes, membrane-bound organelles. Divide by <strong>mitosis</strong>; prokaryotes divide by <strong>binary fission</strong>.</p><p>Viruses are acellular: nucleic acid + protein coat, no metabolism — replicate only inside host cells. Not classified as living by most definitions.</p>'}
   ],
   quiz:[
    {q:'Resolution is defined as', options:['image size/actual size','minimum separable distance between two objects','total magnification','light intensity'], answer:1, explain:'Resolution: the smallest distance at which two points are seen as separate.'},
    {q:'TEM differs from SEM in that TEM', options:['shows 3D surfaces','transmits electrons through thin sections (high resolution, 2D)','uses light','shows living cells'], answer:1, explain:'TEM: electrons pass through ultra-thin sections — internal detail, very high resolution.'},
    {q:'Protein synthesis occurs on', options:['lysosomes','ribosomes','Golgi','smooth ER'], answer:1, explain:'Ribosomes (on RER or free) translate mRNA into polypeptides.'},
    {q:'The site of aerobic respiration is the', options:['chloroplast','mitochondrion','nucleus','ribosome'], answer:1, explain:'Mitochondria: Krebs cycle (matrix) + oxidative phosphorylation (cristae).'},
    {q:'Plant cells differ from animal cells in having', options:['mitochondria','cell wall, large vacuole, chloroplasts','nucleus','ribosomes'], answer:1, explain:'Cellulose wall, permanent vacuole and chloroplasts are plant features.'},
    {q:'Prokaryotic DNA is', options:['linear with histones','circular, in the nucleoid','in a nucleus','absent'], answer:1, explain:'Bacteria: circular DNA free in cytoplasm (nucleoid region), plus plasmids.'},
    {q:'Bacterial cell walls are made of', options:['cellulose','peptidoglycan (murein)','chitin','lignin'], answer:1, explain:'Peptidoglycan — target of penicillin.'},
    {q:'A chloroplast image 30 mm long at ×15 000 has actual length', options:['2 μm','450 μm','0.5 μm','20 μm'], answer:0, explain:'30 mm/15 000 = 0.002 mm = 2 μm.'},
    {q:'Goblet cells have extensive RER and Golgi because they', options:['photosynthesise','secrete mucus (protein)','contract','absorb water'], answer:1, explain:'Secretory cells need protein synthesis (RER) and packaging (Golgi).'},
    {q:'Viruses are considered non-living because they', options:['are too small','lack cellular structure and independent metabolism','have DNA','cause disease'], answer:1, explain:'Acellular: no organelles, no metabolism outside a host.'}
   ]},
  {id:'al-bio-t2', title:'Biological molecules (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t2-l1', title:'Carbohydrates', html:'<h3>Carbohydrates</h3><p><strong>Monosaccharides:</strong> glucose, fructose, galactose (hexoses, C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>); ribose/deoxyribose (pentoses). <strong>Glycosidic bonds</strong> form by <strong>condensation</strong> (water removed): maltose = glucose + glucose (α-1,4); sucrose = glucose + fructose; lactose = glucose + galactose.</p><p><strong>Polysaccharides:</strong> <strong>starch</strong> (amylose: α-1,4 coiled; amylopectin: α-1,4 + α-1,6 branches — plant storage), <strong>glycogen</strong> (highly branched α — animal storage, rapid mobilisation), <strong>cellulose</strong> (β-1,4 — straight chains, H-bonded microfibrils — structural).</p><p>Tests: <strong>Benedict’s</strong> (reducing sugars → brick-red ppt on heating); non-reducing sugars: hydrolyse with HCl first, then Benedict’s. <strong>Iodine</strong> → blue-black with starch.</p>'},
    {id:'al-bio-t2-l2', title:'Lipids and proteins', html:'<h3>Lipids and proteins</h3><p><strong>Triglyceride:</strong> glycerol + 3 fatty acids (ester bonds, condensation). Saturated (no C=C — straight, pack tightly, solid) vs unsaturated (C=C kinks — liquid oils). <strong>Phospholipids:</strong> glycerol + 2 fatty acids + phosphate — hydrophilic head, hydrophobic tails → bilayers.</p><p><strong>Proteins:</strong> amino acids joined by <strong>peptide bonds</strong> (condensation). Structure: primary (sequence), secondary (α-helix/β-sheet, H-bonds), tertiary (3D: H-bonds, ionic, disulfide, hydrophobic), quaternary (multiple polypeptides, e.g. haemoglobin, collagen).</p><p>Test: <strong>biuret</strong> (purple with peptide bonds); <strong>emulsion test</strong> for lipids (ethanol → water → white emulsion).</p>'},
    {id:'al-bio-t2-l3', title:'Water and hydrogen bonding', html:'<h3>Water and hydrogen bonding</h3><p>Water is <strong>polar</strong> with <strong>hydrogen bonding</strong> between molecules, giving: high <strong>specific heat capacity</strong> (stable temperatures), high <strong>latent heat</strong> (cooling by sweating), <strong>cohesion</strong> (transpiration pull, surface tension), excellent <strong>solvent</strong> for polar/ionic substances, and <strong>density anomaly</strong> (ice floats — insulates lakes).</p><p>Hydrolysis (adding water) breaks glycosidic/peptide/ester bonds — digestion. Condensation builds them — synthesis.</p><p>Exam reasoning: always link a property of water to H-bonding explicitly, then to its biological role.</p>'}
   ],
   quiz:[
    {q:'Maltose is formed from', options:['glucose + fructose','glucose + glucose','glucose + galactose','fructose + fructose'], answer:1, explain:'Maltose: two glucose units, α-1,4 glycosidic bond.'},
    {q:'Cellulose differs from starch in', options:['monomer type','β-1,4 linkages giving straight chains','being branched','containing nitrogen'], answer:1, explain:'β-glucose → β-1,4 bonds: straight chains H-bonded into microfibrils.'},
    {q:'Benedict’s test detects', options:['starch','reducing sugars','lipids','proteins'], answer:1, explain:'Reducing sugars reduce blue Cu<sup>2+</sup> → brick-red Cu<sub>2</sub>O on heating.'},
    {q:'A non-reducing sugar is tested by', options:['iodine','hydrolysing with HCl first, then Benedict’s','biuret','emulsion'], answer:1, explain:'Acid hydrolysis breaks sucrose → glucose + fructose (reducing).'},
    {q:'Saturated fatty acids', options:['contain C=C','have no C=C (straight chains)','are always liquid','contain glycerol'], answer:1, explain:'Saturated = maximum H, no double bonds; pack tightly → solid fats.'},
    {q:'Phospholipids form bilayers because', options:['they are fully hydrophobic','they have hydrophilic heads and hydrophobic tails','they contain cholesterol','they are charged'], answer:1, explain:'Amphipathic: heads face water, tails hide inside.'},
    {q:'Protein tertiary structure is stabilised by', options:['peptide bonds only','H-bonds, ionic bonds, disulfide bridges, hydrophobic interactions','glycosidic bonds','ester bonds'], answer:1, explain:'Multiple bond types fold the polypeptide into its 3D shape.'},
    {q:'The biuret test gives', options:['brick-red ppt','purple with proteins','blue-black','white emulsion'], answer:1, explain:'Cu<sup>2+</sup> in alkali → violet complex with peptide bonds.'},
    {q:'Ice floats because', options:['it is warm','H-bonding forms an open lattice less dense than water','it contains salt','of surface tension'], answer:1, explain:'Open hexagonal H-bonded lattice: lower density than liquid water.'},
    {q:'Water’s high specific heat capacity is due to', options:['covalent bonds','hydrogen bonding absorbing energy','its low mass','dissolved ions'], answer:1, explain:'Much energy needed to break H-bonds → temperature changes slowly.'}
   ]},
  {id:'al-bio-t3', title:'Enzymes (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t3-l1', title:'Mode of action', html:'<h3>Mode of action</h3><p>Enzymes are <strong>globular protein</strong> biological catalysts. <strong>Active site</strong>: the region binding substrate. <strong>Lock-and-key</strong> (rigid fit) vs <strong>induced fit</strong> (active site moulds around substrate — current model).</p><p>How they speed reactions: <strong>lower activation energy</strong> — by straining bonds, bringing substrates together in the right orientation, or providing an alternative pathway. They are unchanged at the end and reusable.</p><p><strong>Specificity:</strong> each enzyme catalyses one/few reactions (e.g. amylase → starch, maltase → maltose) because only complementary substrates fit the active site.</p>'},
    {id:'al-bio-t3-l2', title:'Factors affecting enzyme activity', html:'<h3>Factors affecting enzyme activity</h3><p><strong>Temperature:</strong> rate rises to an <strong>optimum</strong> (more kinetic energy → more successful collisions), then falls sharply as the enzyme <strong>denatures</strong> (H-bonds break, tertiary structure lost, active site shape destroyed). Denaturation is usually irreversible.</p><p><strong>pH:</strong> optimum pH (e.g. pepsin ~2, amylase ~7); extremes denature (charges on R groups change → bonds break). <strong>Substrate concentration:</strong> rate rises then plateaus (V<sub>max</sub>) when all active sites are saturated — <strong>Michaelis–Menten</strong> curve.</p><p><strong>Enzyme concentration:</strong> rate proportional (more active sites) at fixed substrate excess.</p>'},
    {id:'al-bio-t3-l3', title:'Inhibitors', html:'<h3>Inhibitors</h3><p><strong>Competitive inhibitors</strong> resemble the substrate and block the active site — overcome by adding more substrate (V<sub>max</sub> unchanged, K<sub>m</sub> increased). <strong>Non-competitive</strong> bind elsewhere, distorting the active site — cannot be overcome (V<sub>max</sub> reduced).</p><p><strong>End-product inhibition:</strong> final product inhibits an earlier enzyme (negative feedback) — e.g. in metabolic pathways. <strong>Poisons</strong> (cyanide, heavy metals) are often irreversible inhibitors.</p><p>Investigating: measure initial rate of reaction (e.g. O<sub>2</sub> from catalase + H<sub>2</sub>O<sub>2</sub>) while varying one factor; control others; repeat and average.</p>'}
   ],
   quiz:[
    {q:'The induced-fit model states', options:['the substrate is rigid','the active site moulds around the substrate','enzymes are used up','any substrate fits'], answer:1, explain:'The active site changes shape slightly to fit the substrate precisely.'},
    {q:'Enzymes speed reactions by', options:['raising activation energy','lowering activation energy','being used up','heating the mixture'], answer:1, explain:'Alternative pathway of lower E<sub>a</sub>.'},
    {q:'Above the optimum temperature, rate falls because', options:['substrate runs out','the enzyme denatures','molecules slow down','pH changes'], answer:1, explain:'Heat breaks the bonds holding tertiary structure: active site deformed irreversibly.'},
    {q:'At high substrate concentration the rate plateaus because', options:['enzyme denatures','all active sites are saturated (V<sub>max</sub>)','substrate inhibits','pH shifts'], answer:1, explain:'No free active sites left: rate limited by enzyme turnover.'},
    {q:'A competitive inhibitor', options:['binds away from the active site','blocks the active site; overcome by more substrate','denatures the enzyme','increases V<sub>max</sub>'], answer:1, explain:'Competes for the active site; excess substrate outcompetes it.'},
    {q:'A non-competitive inhibitor', options:['can be overcome by substrate','binds elsewhere, distorting the active site; V<sub>max</sub> falls','increases rate','is always reversible'], answer:1, explain:'Binds at an allosteric site: shape change cannot be overcome by more substrate.'},
    {q:'End-product inhibition is an example of', options:['positive feedback','negative feedback','denaturation','competition'], answer:1, explain:'Product inhibits its own synthesis pathway — self-regulation.'},
    {q:'Pepsin’s optimum pH (~2) suits', options:['the mouth','the stomach','the small intestine','blood'], answer:1, explain:'Stomach HCl gives pH ~2 for pepsin.'},
    {q:'Enzyme specificity is due to', options:['temperature','the shape of the active site','pH','concentration'], answer:1, explain:'Only complementary substrates fit and bind.'},
    {q:'Measuring initial rate avoids', options:['using a stopwatch','complications from falling substrate / product inhibition','denaturation','saturation'], answer:1, explain:'At t = 0, [S] is known and product effects are negligible.'}
   ]},
  {id:'al-bio-t4', title:'Cell membranes and transport (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t4-l1', title:'The fluid mosaic model', html:'<h3>The fluid mosaic model</h3><p><strong>Fluid mosaic model:</strong> phospholipid bilayer with embedded proteins — “fluid” (molecules move laterally) and “mosaic” (protein pattern). Components: <strong>phospholipids</strong> (barrier), <strong>cholesterol</strong> (mechanical stability, reduces fluidity changes), <strong>intrinsic/extrinsic proteins</strong> (transport, receptors, enzymes), <strong>glycolipids/glycoproteins</strong> (cell recognition, antigens).</p><p>Roles: <strong>channel proteins</strong> (e.g. aquaporins for water), <strong>carrier proteins</strong> (facilitated diffusion, active transport), <strong>receptors</strong> (hormones), <strong>cell-surface antigens</strong>.</p><p>The bilayer is <strong>selectively permeable</strong>: small non-polar molecules (O<sub>2</sub>, CO<sub>2</sub>) diffuse through; ions and large polar molecules need proteins.</p>'},
    {id:'al-bio-t4-l2', title:'Diffusion, osmosis and active transport', html:'<h3>Diffusion, osmosis and active transport</h3><p><strong>Diffusion:</strong> net movement down a concentration gradient (passive). <strong>Facilitated diffusion:</strong> via channel/carrier proteins (still passive, e.g. glucose into some cells, ions). <strong>Osmosis:</strong> water moves across a partially permeable membrane from high to low water potential.</p><p><strong>Active transport:</strong> against the gradient using ATP and carrier proteins (e.g. Na<sup>+</sup>/K<sup>+</sup> pump; mineral uptake by roots). <strong>Endo/exocytosis:</strong> bulk transport via vesicles (e.g. secretion, phagocytosis).</p><p><strong>Water potential ψ:</strong> pure water = 0 kPa; solutions negative. Water moves from high (less negative) to low (more negative) ψ.</p>'},
    {id:'al-bio-t4-l3', title:'Effects of osmosis on cells', html:'<h3>Effects of osmosis on cells</h3><p>Animal cells: in <strong>hypotonic</strong> solution → water in → <strong>lyse (burst)</strong>; in <strong>hypertonic</strong> → water out → <strong>crenate (shrivel)</strong>. Plant cells: hypotonic → <strong>turgid</strong> (wall prevents bursting); hypertonic → <strong>plasmolysed</strong> (membrane pulls from wall); <strong>incipient plasmolysis</strong> at the tipping point.</p><p>Investigating: potato cylinders in sucrose solutions of varying concentration; find the concentration with no mass change = tissue water potential.</p><p>Surface area to volume ratio: small cells exchange faster — limits cell size; large organisms need transport systems.</p>'}
   ],
   quiz:[
    {q:'The fluid mosaic model describes', options:['a solid wall','phospholipid bilayer with mobile embedded proteins','a single lipid layer','a protein wall'], answer:1, explain:'Fluid (lateral movement) + mosaic (protein pattern).'},
    {q:'Cholesterol in membranes', options:['transports ions','adds mechanical stability','forms channels','is an antigen'], answer:1, explain:'Regulates fluidity and strengthens the bilayer.'},
    {q:'Facilitated diffusion differs from simple diffusion in', options:['needing ATP','using proteins but still moving down a gradient','moving against the gradient','needing vesicles'], answer:1, explain:'Protein-mediated but passive: no ATP, down the gradient.'},
    {q:'Osmosis is the movement of', options:['solute through a membrane','water across a partially permeable membrane from high to low water potential','ions with ATP','proteins'], answer:1, explain:'Water follows its water-potential gradient.'},
    {q:'Active transport requires', options:['a concentration gradient only','ATP and carrier proteins to move against the gradient','channel proteins','vesicles only'], answer:1, explain:'Energy + specific carriers pump substances uphill.'},
    {q:'Pure water has water potential', options:['−100 kPa','0 kPa','+100 kPa','−1000 kPa'], answer:1, explain:'ψ = 0 for pure water; solutions are negative.'},
    {q:'A red blood cell in distilled water will', options:['crenate','lyse (burst)','plasmolyse','stay unchanged'], answer:1, explain:'Hypotonic: water rushes in; no wall → bursts.'},
    {q:'A plant cell in strong sucrose solution becomes', options:['turgid','plasmolysed','lysed','flaccid only'], answer:1, explain:'Hypertonic: water leaves; membrane pulls away from the wall.'},
    {q:'Aquaporins are', options:['carrier proteins for glucose','channel proteins for water','active pumps','receptors'], answer:1, explain:'Specific water channels allowing rapid osmosis.'},
    {q:'Small cells are efficient at exchange because', options:['they have nuclei','high surface area to volume ratio','they lack walls','they are round'], answer:1, explain:'High SA:V → short diffusion distances, fast exchange.'}
   ]},
  {id:'al-bio-t5', title:'The mitotic cell cycle (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t5-l1', title:'The cell cycle and DNA replication', html:'<h3>The cell cycle and DNA replication</h3><p><strong>Cell cycle:</strong> interphase (G<sub>1</sub> growth, S DNA replication, G<sub>2</sub> preparation) + mitosis + cytokinesis. Most time is spent in interphase.</p><p><strong>Semi-conservative replication:</strong> DNA helicase unwinds; each strand is a template; DNA polymerase adds complementary nucleotides (A–T, C–G); two identical daughter molecules, each with one old and one new strand. Needs ATP and is very accurate (proofreading).</p><p><strong>Chromosomes:</strong> DNA + histone proteins; visible as condensed chromatids during mitosis. <strong>Homologous chromosomes:</strong> same genes, one from each parent.</p>'},
    {id:'al-bio-t5-l2', title:'Stages of mitosis', html:'<h3>Stages of mitosis</h3><p><strong>Prophase:</strong> chromosomes condense, nuclear envelope breaks down, spindle forms. <strong>Metaphase:</strong> chromosomes line up on the equator, attached to spindle fibres at centromeres. <strong>Anaphase:</strong> sister chromatids pulled apart to poles (shortening spindle fibres). <strong>Telophase:</strong> nuclear envelopes reform, chromosomes decondense. <strong>Cytokinesis:</strong> cytoplasm divides (cell plate in plants, cleavage furrow in animals).</p><p>Result: two genetically identical diploid daughter cells. Roles: growth, repair, asexual reproduction.</p><p>Recognise stages in micrographs: metaphase = line at equator; anaphase = V-shapes moving apart.</p>'},
    {id:'al-bio-t5-l3', title:'Cancer and the cell cycle', html:'<h3>Cancer and the cell cycle</h3><p><strong>Cancer:</strong> uncontrolled mitosis — cells divide without normal checks. <strong>Mutations</strong> in proto-oncogenes (→ oncogenes, promote division) or tumour suppressor genes (fail to stop division) cause it.</p><p>Causes: carcinogens (tobacco smoke, UV, asbestos, some viruses). Tumours: benign (contained) vs malignant (invade, metastasise).</p><p>Treatments: surgery, radiotherapy (damages DNA of dividing cells), chemotherapy (targets rapidly dividing cells — side effects on hair, gut lining, bone marrow).</p>'}
   ],
   quiz:[
    {q:'DNA replication occurs in', options:['G<sub>1</sub>','S phase','G<sub>2</sub>','mitosis'], answer:1, explain:'S (synthesis) phase of interphase.'},
    {q:'Semi-conservative replication means', options:['half the DNA is lost','each daughter molecule has one old and one new strand','DNA is halved','only one strand replicates'], answer:1, explain:'Each original strand templates a new complementary strand.'},
    {q:'In metaphase, chromosomes', options:['condense','line up on the equator','separate to poles','decondense'], answer:1, explain:'Attached at centromeres, aligned on the metaphase plate.'},
    {q:'Sister chromatids separate during', options:['prophase','metaphase','anaphase','telophase'], answer:2, explain:'Spindle fibres shorten, pulling chromatids to opposite poles.'},
    {q:'Cytokinesis in plant cells uses', options:['a cleavage furrow','a cell plate','spindle fibres','centrioles'], answer:1, explain:'Vesicles fuse to form the cell plate (new wall).'},
    {q:'Mitosis produces', options:['4 haploid cells','2 genetically identical diploid cells','2 different cells','gametes'], answer:1, explain:'One division: two identical diploid daughters.'},
    {q:'Cancer is caused by mutations in', options:['any gene','proto-oncogenes or tumour suppressor genes','only viral genes','mitochondrial DNA'], answer:1, explain:'Oncogenes drive division; failed suppressors cannot stop it.'},
    {q:'Chemotherapy side effects (hair loss, nausea) occur because', options:['drugs are acidic','rapidly dividing healthy cells are also hit','patients are weak','radiation leaks'], answer:1, explain:'Drugs target all fast-dividing cells, including hair follicles and gut lining.'},
    {q:'Homologous chromosomes', options:['are identical','carry the same genes, one from each parent','are always joined','exist only in gametes'], answer:1, explain:'Same loci, possibly different alleles; maternal + paternal.'},
    {q:'DNA polymerase', options:['unwinds DNA','adds complementary nucleotides to the new strand','joins Okazaki fragments only','breaks H-bonds'], answer:1, explain:'Synthesises the new strand 5′→3′ using the template.'}
   ]},
  {id:'al-bio-t6', title:'Nucleic acids and protein synthesis (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t6-l1', title:'DNA and RNA structure', html:'<h3>DNA and RNA structure</h3><p><strong>DNA:</strong> double helix; deoxyribose + phosphate backbone; bases A–T, C–G (H-bonds: A=T 2 bonds, C≡G 3 bonds). Antiparallel strands. <strong>RNA:</strong> single-stranded; ribose; uracil instead of thymine. Types: <strong>mRNA</strong> (carries code), <strong>tRNA</strong> (brings amino acids, anticodon), <strong>rRNA</strong> (ribosome structure).</p><p><strong>Nucleotide</strong> = pentose + phosphate + base. Polynucleotides join by <strong>phosphodiester bonds</strong> (condensation).</p><p><strong>ATP:</strong> adenine + ribose + 3 phosphates — universal energy currency; hydrolysis of terminal phosphate releases energy for active transport, muscle contraction, biosynthesis.</p>'},
    {id:'al-bio-t6-l2', title:'Transcription and translation', html:'<h3>Transcription and translation</h3><p><strong>Transcription</strong> (nucleus): RNA polymerase binds promoter; DNA unwinds; free RNA nucleotides pair with the template strand; mRNA synthesised 5′→3′; mRNA leaves via nuclear pores. <strong>Translation</strong> (ribosome): mRNA codons read; tRNA anticodons bring specific amino acids; <strong>peptide bonds</strong> form between adjacent amino acids; polypeptide released at a stop codon.</p><p><strong>Triplet code:</strong> 3 bases = 1 amino acid; <strong>degenerate</strong> (multiple codons per amino acid), <strong>non-overlapping</strong>, universal. Start codon AUG (methionine); stop codons UAA, UAG, UGA.</p><p>Worked example: DNA template TAC–CGA → mRNA AUG–GCU → amino acids Met–Ala.</p>'},
    {id:'al-bio-t6-l3', title:'Mutations', html:'<h3>Mutations</h3><p><strong>Gene mutation:</strong> change in DNA base sequence. Types: <strong>substitution</strong> (one base swapped — may be silent/missense/nonsense), <strong>deletion/insertion</strong> (frameshift — shifts all downstream codons, usually severe).</p><p>Effects: <strong>silent</strong> (same amino acid — degeneracy), <strong>missense</strong> (different amino acid — e.g. sickle cell: GAG→GTG, glutamate→valine), <strong>nonsense</strong> (premature stop — truncated protein).</p><p><strong>Mutagens:</strong> radiation, certain chemicals, some viruses. Most mutations are neutral or harmful; rarely beneficial (raw material for evolution).</p>'}
   ],
   quiz:[
    {q:'In DNA, adenine pairs with', options:['guanine','thymine','cytosine','uracil'], answer:1, explain:'A–T (2 H-bonds); C–G (3 H-bonds).'},
    {q:'RNA differs from DNA in having', options:['thymine','uracil and ribose','a double helix','deoxyribose'], answer:1, explain:'RNA: ribose sugar, uracil instead of thymine, usually single-stranded.'},
    {q:'tRNA’s role is to', options:['copy DNA','bring amino acids to the ribosome','form the ribosome','make mRNA'], answer:1, explain:'Anticodon pairs with mRNA codon; carries the specific amino acid.'},
    {q:'Transcription occurs in the', options:['ribosome','nucleus','cytoplasm','mitochondrion'], answer:1, explain:'RNA polymerase synthesises mRNA from the DNA template in the nucleus.'},
    {q:'The genetic code is degenerate, meaning', options:['it is broken','multiple codons code for one amino acid','it overlaps','it varies between species'], answer:1, explain:'E.g. six codons for leucine — protects against point mutations.'},
    {q:'A frameshift mutation is caused by', options:['substitution','insertion or deletion of bases','duplication of a gene','inversion'], answer:1, explain:'Adding/removing bases (not in threes) shifts every downstream codon.'},
    {q:'Sickle cell anaemia results from', options:['a frameshift','a base substitution (GAG→GTG)','a deletion','chromosome loss'], answer:1, explain:'Missense: glutamate → valine in β-globin.'},
    {q:'ATP releases energy when', options:['adenine is removed','the terminal phosphate is hydrolysed','ribose breaks','it is synthesised'], answer:1, explain:'ATP → ADP + P<sub>i</sub>: exergonic, coupled to cellular work.'},
    {q:'Peptide bonds form during', options:['transcription','translation','replication','splicing'], answer:1, explain:'Ribosome links adjacent amino acids as tRNAs bring them in.'},
    {q:'A nonsense mutation', options:['has no effect','creates a premature stop codon','changes one amino acid','duplicates the gene'], answer:1, explain:'Substitution creating UAA/UAG/UGA early → truncated, usually non-functional protein.'}
   ]}
,
  {id:'al-bio-t7', title:'Transport in plants (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t7-l1', title:'Xylem and phloem structure', html:'<h3>Xylem and phloem structure</h3><p><strong>Xylem vessels:</strong> dead, hollow tubes with lignified walls and pits — carry water/minerals up from roots. No end walls or cytoplasm → low resistance. <strong>Phloem sieve tubes:</strong> living, no nucleus, perforated sieve plates; <strong>companion cells</strong> (with nucleus, many mitochondria) load solutes.</p><p>Adaptations: xylem’s lignin gives support and waterproofing; pits allow lateral water movement; narrow diameter aids capillarity and cohesion.</p><p>Distribution: vascular bundles — xylem inside, phloem outside (dicot stem ring; root central xylem star).</p>'},
    {id:'al-bio-t7-l2', title:'Transpiration and the transpiration stream', html:'<h3>Transpiration and the transpiration stream</h3><p><strong>Transpiration:</strong> evaporation of water from leaf cell walls into air spaces, then diffusion out through stomata. <strong>Transpiration stream:</strong> root → xylem → leaf, driven by the <strong>cohesion–tension</strong> mechanism: water molecules cohere (H-bonds), adhere to xylem walls, and are pulled up as a continuous column by transpiration pull.</p><p>Factors: <strong>light</strong> (stomata open) ↑; <strong>temperature</strong> ↑ (faster evaporation/diffusion) ↑; <strong>humidity</strong> ↓ gradient → ↓; <strong>wind</strong> (removes saturated air) ↑. Measured with a <strong>potometer</strong> (water uptake ≈ transpiration).</p><p><strong>Xerophyte adaptations:</strong> sunken stomata, hairy leaves, rolled leaves, thick cuticle, small leaves — reduce water loss.</p>'},
    {id:'al-bio-t7-l3', title:'Translocation', html:'<h3>Translocation</h3><p><strong>Translocation:</strong> movement of sucrose (and amino acids) in phloem from <strong>source</strong> (photosynthesising leaf, storage organ in spring) to <strong>sink</strong> (roots, fruits, growing regions). Bidirectional (unlike xylem).</p><p><strong>Mass flow hypothesis:</strong> sucrose actively loaded at source → water follows by osmosis → high hydrostatic pressure; at sink, sucrose unloaded → water leaves → low pressure; pressure gradient drives bulk flow through sieve plates.</p><p>Evidence: aphid stylets tap sieve tubes (exude sugary sap); ringing experiments (removing phloem stops transport); tracers (<sup>14</sup>C) move source→sink. Companion cells’ many mitochondria support active loading.</p>'}
   ],
   quiz:[
    {q:'Xylem vessels are adapted for transport by being', options:['living with cytoplasm','dead, hollow, lignified tubes','nucleated','full of sap'], answer:1, explain:'No protoplasm/end walls: unobstructed water column; lignin gives strength.'},
    {q:'Companion cells are needed because sieve tube elements', options:['are dead','lack nuclei','are too narrow','lack walls'], answer:1, explain:'Companion cells (nucleus, mitochondria) control and energise sieve tubes.'},
    {q:'The cohesion–tension theory states', options:['roots push water up','transpiration pulls a continuous H-bonded water column up','water is pumped','osmosis lifts water'], answer:1, explain:'Evaporation creates tension; cohesion/adhesion maintain the column.'},
    {q:'Which factor decreases transpiration?', options:['high light','high temperature','high humidity','wind'], answer:2, explain:'Humid air reduces the diffusion gradient for water vapour.'},
    {q:'A potometer measures', options:['photosynthesis','water uptake (≈ transpiration)','respiration','growth'], answer:1, explain:'Water absorbed by the cut shoot replaces transpired water.'},
    {q:'Sunken stomata in xerophytes', options:['increase water loss','trap moist air, reducing the diffusion gradient','increase photosynthesis','attract pollinators'], answer:1, explain:'Sheltered pits hold humid air → slower diffusion out.'},
    {q:'Translocation moves sucrose from', options:['roots to leaves only','source to sink','xylem to phloem','soil to root'], answer:1, explain:'Source (leaf/storage) → sink (growth/storage), in phloem.'},
    {q:'Mass flow is driven by', options:['capillarity','hydrostatic pressure gradient from source to sink','active transport along the tube','gravity'], answer:1, explain:'Osmotic water entry at source builds pressure pushing sap to sinks.'},
    {q:'Aphid stylet experiments show', options:['xylem contents','phloem sap is sugary and under pressure','transpiration rate','root pressure'], answer:1, explain:'Stylets in sieve tubes exude sucrose-rich sap, proving contents and pressure.'},
    {q:'Unlike xylem transport, translocation is', options:['unidirectional','bidirectional','passive only','upward only'], answer:1, explain:'Phloem carries sap to whatever sinks need it — up or down.'}
   ]},
  {id:'al-bio-t8', title:'Transport in mammals (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t8-l1', title:'Blood vessels', html:'<h3>Blood vessels</h3><p><strong>Arteries:</strong> thick muscle + elastic wall — withstand high pressure, smooth flow (elastic recoil). <strong>Arterioles:</strong> muscle sphincters control flow distribution. <strong>Capillaries:</strong> one cell thick endothelium, narrow lumen — short diffusion distance; slow flow. <strong>Veins:</strong> thin wall, wide lumen, <strong>valves</strong> prevent backflow; skeletal muscle contraction pushes blood.</p><p>Adaptations link to function: artery wall thickness ∝ pressure; capillary thinness ∝ exchange; vein valves ∝ low pressure.</p><p><strong>Tissue fluid:</strong> forms at the arteriole end (high hydrostatic pressure forces plasma out); most reabsorbed at the venule end (lower pressure, water potential gradient); remainder drains into <strong>lymph</strong>.</p>'},
    {id:'al-bio-t8-l2', title:'The heart and cardiac cycle', html:'<h3>The heart and cardiac cycle</h3><p><strong>Cardiac cycle:</strong> atrial systole (atria contract → ventricles fill) → ventricular systole (ventricles contract → semilunar valves open, blood to arteries; AV valves shut → “lubb”) → diastole (all relax; AV valves open). Valves ensure one-way flow: <strong>AV (bicuspid/tricuspid)</strong> and <strong>semilunar</strong>.</p><p><strong>Initiation:</strong> <strong>SAN</strong> (pacemaker) fires → atria contract → <strong>AVN</strong> delays → <strong>bundle of His/Purkyne tissue</strong> → ventricles contract from apex up. <strong>Myogenic:</strong> the heart initiates its own beat.</p><p>Control: medulla via <strong>sympathetic</strong> (adrenaline — faster) and <strong>parasympathetic/vagus</strong> (slower) nerves; chemoreceptors detect CO<sub>2</sub>/pH.</p>'},
    {id:'al-bio-t8-l3', title:'Haemoglobin and oxygen transport', html:'<h3>Haemoglobin and oxygen transport</h3><p><strong>Haemoglobin:</strong> 4 haem groups (each binds one O<sub>2</sub>) + globin chains. <strong>Oxygen dissociation curve:</strong> sigmoid — loading O<sub>2</sub> easily at high pO<sub>2</sub> (lungs), unloading at low pO<sub>2</sub> (tissues). <strong>Cooperative binding:</strong> each O<sub>2</sub> bound makes the next easier.</p><p><strong>Bohr effect:</strong> high CO<sub>2</sub> (low pH) shifts the curve right → Hb releases O<sub>2</sub> more readily where respiration is active. <strong>Myoglobin</strong> (muscles) has a steeper curve — loads O<sub>2</sup> from Hb and releases only at very low pO<sub>2</sub> (reserve).</p><p><strong>CO<sub>2</sub> transport:</strong> ~85% as hydrogencarbonate ions (carbonic anhydrase: CO<sub>2</sub> + H<sub>2</sub>O → H<sub>2</sub>CO<sub>3</sub> → H<sup>+</sup> + HCO<sub>3</sub><sup>−</sup>); chloride shift maintains charge balance; some as carbamino compounds; little dissolved.</p>'}
   ],
   quiz:[
    {q:'Arteries have thick elastic walls to', options:['prevent backflow','withstand high pressure and smooth the pulse','slow blood down','allow exchange'], answer:1, explain:'Elastic recoil maintains pressure during diastole; muscle adjusts diameter.'},
    {q:'Veins contain valves because', options:['pressure is high','pressure is low — prevent backflow','blood is thick','they are narrow'], answer:1, explain:'Low pressure: valves + skeletal muscle pump keep blood moving to the heart.'},
    {q:'Tissue fluid is formed mainly by', options:['osmosis','hydrostatic pressure forcing plasma out at the arteriole end','active transport','diffusion of cells'], answer:1, explain:'High blood pressure at the arteriole end pushes fluid out through capillary walls.'},
    {q:'In the cardiac cycle, the AV valves close at the start of', options:['atrial systole','ventricular systole','diastole','filling'], answer:1, explain:'Ventricular pressure exceeds atrial: AV valves slam shut (first heart sound).'},
    {q:'The SAN is the', options:['atrioventricular node','sinoatrial node — pacemaker','bundle of His','Purkyne tissue'], answer:1, explain:'SAN initiates each wave of excitation: sets the heart rate.'},
    {q:'The AVN delays the impulse to', options:['slow the heart','let atria finish emptying before ventricles contract','save energy','prevent fibrillation'], answer:1, explain:'~0.1 s delay ensures ventricular filling before ventricular systole.'},
    {q:'The oxygen dissociation curve is sigmoid because of', options:['pH','cooperative binding of O<sub>2</sub>','temperature','CO<sub>2</sub>'], answer:1, explain:'Each O<sub>2</sub> bound eases the next: steep middle section.'},
    {q:'The Bohr effect is', options:['O<sub>2</sub> binding to myoglobin','high CO<sub>2</sub> shifting the curve right, aiding O<sub>2</sub> release','low pH increasing loading','temperature effect'], answer:1, explain:'Active tissues (high CO<sub>2</sub>/H<sup>+</sup>) get more O<sub>2</sub> released.'},
    {q:'Most CO<sub>2</sub> is carried as', options:['dissolved gas','hydrogencarbonate ions','carbaminohaemoglobin only','carbonic acid'], answer:1, explain:'~85% as HCO<sub>3</sub><sup>−</sup> in plasma (carbonic anhydrase in RBCs).'},
    {q:'Myoglobin’s dissociation curve lies left of haemoglobin’s because', options:['it binds 4 O<sub>2</sub>','it has higher affinity — releases O<sub>2</sub> only at very low pO<sub>2</sub>','it is in blood','it is larger'], answer:1, explain:'Single haem: steep curve, O<sub>2</sub> reserve for respiring muscle.'}
   ]},
  {id:'al-bio-t9', title:'Gas exchange (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t9-l1', title:'The mammalian gas exchange system', html:'<h3>The mammalian gas exchange system</h3><p>Path: nasal cavity → trachea (C-shaped cartilage rings — keep open) → bronchi → bronchioles → <strong>alveoli</strong>. Goblet cells secrete mucus; ciliated epithelium sweeps it up (<strong>mucociliary escalator</strong>).</p><p><strong>Alveoli adaptations:</strong> huge total surface area (~70 m²), one-cell-thick walls, dense capillary network, moist lining, short diffusion distance, ventilation + blood flow maintain gradients.</p><p><strong>Ventilation:</strong> inspiration — external intercostals contract, diaphragm flattens → volume ↑, pressure ↓ → air in. Expiration — muscles relax, elastic recoil → air out. Forced expiration uses internal intercostals/abdominals.</p>'},
    {id:'al-bio-t9-l2', title:'Gas exchange in other organisms', html:'<h3>Gas exchange in other organisms</h3><p><strong>Fish gills:</strong> filaments with lamellae — huge surface area; <strong>counter-current flow</strong> (water vs blood in opposite directions) maintains a gradient along the whole lamella → ~80% O<sub>2</sub> extraction. Gill rakers/operculum ventilate.</p><p><strong>Insects:</strong> <strong>tracheae</strong> open via <strong>spiracles</strong>; branch to <strong>tracheoles</strong> delivering O<sub>2</sub> directly to tissues (fluid-filled ends). Abdominal pumping ventilates; spiracles close to reduce water loss.</p><p><strong>Plants:</strong> stomata + air spaces; lenticels in stems. All gas exchange surfaces share: large area, thin, moist, good ventilation/blood supply, steep gradients.</p>'},
    {id:'al-bio-t9-l3', title:'Smoking and lung disease', html:'<h3>Smoking and lung disease</h3><p>Tobacco smoke: <strong>tar</strong> (carcinogen — lung cancer), <strong>nicotine</strong> (addictive; constricts vessels, raises BP), <strong>CO</strong> (binds haemoglobin → carboxyhaemoglobin, reducing O<sub>2</sub> transport).</p><p><strong>Chronic bronchitis:</strong> tar paralyses cilia → mucus builds → smoker’s cough, infections. <strong>Emphysema:</strong> phagocytes destroy alveolar walls → fewer, larger alveoli → reduced surface area → breathlessness. <strong>Lung cancer:</strong> tar mutates DNA → uncontrolled division.</p><p>Evidence: epidemiological correlation (dose–response between smoking and disease); risk falls after quitting. Passive smoking also harms.</p>'}
   ],
   quiz:[
    {q:'C-shaped cartilage in the trachea', options:['aids swallowing','keeps the airway open','produces mucus','warms air'], answer:1, explain:'Rigid rings prevent collapse during pressure changes; open part faces the oesophagus.'},
    {q:'Alveoli are adapted for exchange by', options:['thick walls','large surface area, thin walls, dense capillaries','dry surfaces','slow blood flow'], answer:1, explain:'Short diffusion distance + huge area + maintained gradients = fast diffusion.'},
    {q:'During inspiration', options:['diaphragm domes up','external intercostals contract, diaphragm flattens','pressure rises','air is forced out'], answer:1, explain:'Volume increases → pressure falls below atmospheric → air flows in.'},
    {q:'Counter-current flow in gills', options:['wastes energy','maintains a diffusion gradient along the whole lamella','slows blood','warms water'], answer:1, explain:'Opposite flows keep water O<sub>2</sub> above blood O<sub>2</sub> throughout: ~80% extraction.'},
    {q:'Insects reduce water loss by', options:['closing spiracles','thinner tracheae','faster pumping','larger spiracles'], answer:0, explain:'Spiracles open only when needed, limiting evaporation.'},
    {q:'CO in smoke harms because', options:['it is acidic','it binds haemoglobin, blocking O<sub>2</sub> transport','it paralyses cilia','it causes cancer'], answer:1, explain:'Carboxyhaemoglobin: CO binds ~250× more strongly than O<sub>2</sub>.'},
    {q:'Emphysema reduces gas exchange by', options:['thickening walls','destroying alveolar walls → less surface area','blocking bronchi','filling alveoli with mucus'], answer:1, explain:'Fewer, larger alveoli: surface area lost → breathlessness.'},
    {q:'Tar in smoke mainly causes', options:['addiction','paralysed cilia and lung cancer','high blood pressure','anaemia'], answer:1, explain:'Tar: carcinogenic + destroys the mucociliary escalator.'},
    {q:'Nicotine is', options:['a carcinogen','addictive and raises blood pressure','harmless','a bronchodilator'], answer:1, explain:'Stimulates adrenaline: vasoconstriction, higher heart rate/BP; addictive.'},
    {q:'The mucociliary escalator', options:['moves food','sweeps mucus with trapped particles up to the throat','oxygenates blood','filters air in the nose'], answer:1, explain:'Cilia beat mucus (with dust/pathogens) upward to be swallowed.'}
   ]},
  {id:'al-bio-t10', title:'Infectious diseases (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t10-l1', title:'Pathogens and transmission', html:'<h3>Pathogens and transmission</h3><p><strong>Pathogen:</strong> disease-causing organism. Types: <strong>bacteria</strong> (e.g. Mycobacterium tuberculosis — TB; Vibrio cholerae — cholera), <strong>viruses</strong> (HIV, influenza, SARS-CoV-2), <strong>fungi</strong>, <strong>protoctists</strong> (Plasmodium — malaria).</p><p>Transmission: <strong>droplet/airborne</strong> (TB, flu), <strong>contaminated water/food</strong> (cholera), <strong>vector</strong> (mosquito — malaria), <strong>bodily fluids</strong> (HIV), <strong>direct contact</strong>.</p><p><strong>Cholera:</strong> V. cholerae toxin causes massive water/ion loss from the gut → dehydration. Spread by faecally contaminated water. <strong>TB:</strong> airborne droplets; attacks lungs.</p>'},
    {id:'al-bio-t10-l2', title:'The immune response overview and antibiotics', html:'<h3>The immune response overview and antibiotics</h3><p>Barriers: skin, stomach acid, lysozyme, mucus, clotting. <strong>Phagocytes</strong> engulf pathogens (phagocytosis); present antigens. <strong>Lymphocytes:</strong> B cells → plasma cells make <strong>antibodies</strong>; T cells kill infected cells / coordinate.</p><p><strong>Antibiotics</strong> (e.g. penicillin — blocks bacterial cell wall synthesis) kill bacteria or stop growth. <strong>Ineffective against viruses</strong> (no cell wall/metabolism of their own). Misuse → <strong>antibiotic resistance</strong> (natural selection of resistant strains — e.g. MRSA).</p><p>Preventing resistance: complete prescribed courses, avoid antibiotics for viral infections, hygiene, new drug development.</p>'},
    {id:'al-bio-t10-l3', title:'HIV/AIDS', html:'<h3>HIV/AIDS</h3><p><strong>HIV</strong> (retrovirus: RNA + reverse transcriptase) infects <strong>helper T cells</strong> (CD4): attaches → RNA enters → reverse transcriptase makes DNA → integrates (provirus) → new viruses bud off, killing the cell.</p><p>Loss of helper T cells cripples immunity → <strong>AIDS</strong>: opportunistic infections/cancers. Transmission: unprotected sex, blood, mother-to-child. NOT by casual contact.</p><p>Control: education, condoms, screening blood, <strong>antiretroviral drugs</strong> (block reverse transcriptase/protease — manage, not cure). No vaccine yet (high mutation rate).</p>'}
   ],
   quiz:[
    {q:'Cholera is caused by', options:['a virus','the bacterium Vibrio cholerae','a protoctist','a fungus'], answer:1, explain:'V. cholerae: contaminated water; toxin causes severe diarrhoea/dehydration.'},
    {q:'TB spreads mainly by', options:['contaminated water','airborne droplets','mosquitoes','food'], answer:1, explain:'M. tuberculosis: inhaled droplets from coughing.'},
    {q:'Malaria’s vector is the', options:['tsetse fly','female Anopheles mosquito','tick','louse'], answer:1, explain:'Female Anopheles carries Plasmodium between humans.'},
    {q:'Penicillin works by', options:['boosting immunity','blocking bacterial cell-wall synthesis','killing viruses','dissolving toxins'], answer:1, explain:'β-lactam: inhibits peptidoglycan cross-linking; bacteria lyse.'},
    {q:'Antibiotics are ineffective against viruses because', options:['viruses are too small','viruses lack the bacterial targets (cell wall, own metabolism)','viruses are resistant','doses are too low'], answer:1, explain:'No cell wall/protein synthesis machinery of their own to attack.'},
    {q:'Antibiotic resistance spreads by', options:['mutation only','natural selection of resistant strains','vaccination','hygiene'], answer:1, explain:'Resistant mutants survive treatment and multiply — selection.'},
    {q:'HIV infects', options:['B cells','helper T (CD4) cells','red blood cells','phagocytes'], answer:1, explain:'CD4 receptor: helper T cells destroyed → immune collapse.'},
    {q:'HIV is a retrovirus because it', options:['has DNA','carries RNA and reverse transcriptase','lacks a coat','is large'], answer:1, explain:'RNA → DNA via reverse transcriptase, then integrates.'},
    {q:'AIDS results from', options:['the virus directly killing all cells','loss of helper T cells → opportunistic infections','antibiotic failure','autoimmunity'], answer:1, explain:'Immune coordination lost: normally harmless microbes cause disease.'},
    {q:'Cholera is best prevented by', options:['vaccination only','clean water and sanitation','antibiotics','quarantine'], answer:1, explain:'Faecal–oral spread: safe water/sanitation breaks transmission.'}
   ]},
  {id:'al-bio-t11', title:'Immunity (AS)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t11-l1', title:'Antibodies and the immune response', html:'<h3>Antibodies and the immune response</h3><p><strong>Antibody:</strong> Y-shaped protein; <strong>variable region</strong> binds a specific <strong>antigen</strong>; constant region binds phagocytes. Produced by <strong>plasma cells</strong> (cloned B lymphocytes).</p><p><strong>Humoral response:</strong> B cell meets matching antigen → <strong>clonal selection</strong> → plasma cells (antibodies) + <strong>memory B cells</strong>. Antibodies <strong>agglutinate</strong> pathogens, neutralise toxins, opsonise for phagocytes.</p><p><strong>Cell-mediated:</strong> T<sub>h</sub> cells activate; T<sub>k</sub> (killer) cells destroy infected/cancer cells; memory T cells persist.</p>'},
    {id:'al-bio-t11-l2', title:'Active and passive immunity', html:'<h3>Active and passive immunity</h3><p><strong>Active immunity:</strong> own lymphocytes make antibodies + memory cells — slow first response, long-lasting. Natural (infection) or artificial (<strong>vaccination</strong>).</p><p><strong>Passive immunity:</strong> ready-made antibodies given — immediate but short-lived (antibodies broken down, no memory). Natural (across placenta, in breast milk) or artificial (antivenom, anti-tetanus).</p><p><strong>Vaccination:</strong> harmless antigen (dead/attenuated pathogen, toxoid, subunit) → primary response + memory; on real infection, rapid <strong>secondary response</strong> (faster, stronger — IgG) prevents disease. <strong>Herd immunity</strong> protects the unvaccinated when coverage is high.</p>'},
    {id:'al-bio-t11-l3', title:'Monoclonal antibodies', html:'<h3>Monoclonal antibodies</h3><p><strong>Monoclonal antibodies:</strong> identical antibodies from one B-cell clone — made by fusing a B lymphocyte with a <strong>myeloma</strong> (tumour) cell → <strong>hybridoma</strong> (divides indefinitely + makes the antibody).</p><p>Uses: <strong>pregnancy tests</strong> (anti-hCG), blood typing, cancer diagnosis/treatment (targeted drug delivery), ELISA diagnosis. Advantages: specific, pure, unlimited supply.</p><p>Ethical/production issues: animal use (mice), cost, possible immune reactions to mouse antibodies (humanised antibodies reduce this).</p>'}
   ],
   quiz:[
    {q:'Antibodies bind antigens via their', options:['constant region','variable region','stem','sugar chain'], answer:1, explain:'Variable tips are complementary to the specific antigen.'},
    {q:'Plasma cells are', options:['phagocytes','cloned B cells that secrete antibody','T cells','memory cells'], answer:1, explain:'Differentiated B lymphocytes: antibody factories.'},
    {q:'Clonal selection means', options:['random mutation','the matching B cell is stimulated to divide','antibodies clone pathogens','T cells divide'], answer:1, explain:'Antigen selects its complementary B lymphocyte for cloning.'},
    {q:'Active immunity differs from passive in', options:['speed','producing own memory cells — long-lasting','using antibodies','needing lymphocytes'], answer:1, explain:'Active: self-made antibodies + memory (slow, lasting); passive: borrowed antibodies (fast, temporary).'},
    {q:'Vaccination works by', options:['killing pathogens directly','creating memory cells for a rapid secondary response','giving antibiotics','blocking transmission'], answer:1, explain:'Primary response to harmless antigen → memory → fast strong response on exposure.'},
    {q:'Herd immunity', options:['vaccinating animals','high coverage interrupting transmission, protecting the unvaccinated','natural immunity only','isolating the sick'], answer:1, explain:'The pathogen cannot spread when most hosts are immune.'},
    {q:'Hybridomas are made by fusing', options:['two T cells','a B lymphocyte with a myeloma cell','two bacteria','virus + cell'], answer:1, explain:'Combines specific antibody production with indefinite division.'},
    {q:'Monoclonal antibodies in pregnancy tests detect', options:['oestrogen','hCG','progesterone','LH'], answer:1, explain:'Anti-hCG antibodies bind the pregnancy hormone.'},
    {q:'Antibodies help phagocytes by', options:['killing directly','opsonisation — marking pathogens for engulfment','digesting','blocking blood flow'], answer:1, explain:'Coating pathogens (opsonins) aids phagocyte recognition.'},
    {q:'Memory cells enable', options:['immediate passive immunity','a faster, stronger secondary response','antigen variation','tolerance'], answer:1, explain:'Memory B/T cells persist for years, responding rapidly on re-exposure.'}
   ]}
,
  {id:'al-bio-t12', title:'Energy and respiration (A2)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t12-l1', title:'ATP and the stages of respiration', html:'<h3>ATP and the stages of respiration</h3><p><strong>ATP:</strong> the energy currency — energy released by respiration is stored as ATP (ADP + P<sub>i</sub> → ATP needs energy; ATP → ADP + P<sub>i</sub> releases ~30.5 kJ mol<sup>-1</sup>). Used for muscle contraction, active transport, biosynthesis, nerve impulses.</p><p>Four stages: <strong>glycolysis</strong> (cytoplasm: glucose → 2 pyruvate, net 2 ATP, 2 NADH); <strong>link reaction</strong> (mitochondrial matrix: pyruvate → acetyl CoA + CO<sub>2</sub>, NADH); <strong>Krebs cycle</strong> (matrix: acetyl CoA oxidised → CO<sub>2</sub>, 3 NADH + FADH<sub>2</sub> + ATP per turn); <strong>oxidative phosphorylation</strong> (cristae: electron transport chain → ~34 ATP, O<sub>2</sub> final acceptor → H<sub>2</sub>O).</p><p>Total: ~38 ATP per glucose (aerobic). <strong>Respiratory quotient RQ = CO<sub>2</sub> released / O<sub>2</sub> used</strong>: carbohydrate = 1.0, lipid ~0.7, protein ~0.9.</p>'},
    {id:'al-bio-t12-l2', title:'Oxidative phosphorylation and chemiosmosis', html:'<h3>Oxidative phosphorylation and chemiosmosis</h3><p><strong>Chemiosmotic theory:</strong> NADH/FADH<sub>2</sub> donate electrons to the <strong>electron transport chain</strong> on the cristae; energy released pumps <strong>H<sup>+</sup> into the intermembrane space</strong> → electrochemical gradient; H<sup>+</sup> flows back through <strong>ATP synthase</strong>, driving ATP synthesis. Oxygen is the final electron acceptor (forms water).</p><p>Evidence: cristae provide huge surface area; uncouplers (dinitrophenol) destroy the gradient → heat instead of ATP; oxygen uptake matches ATP output.</p><p><strong>Anaerobic respiration:</strong> no O<sub>2</sub> → pyruvate → lactate (animals) or ethanol + CO<sub>2</sub> (yeast/plants), regenerating NAD<sup>+</sup> for glycolysis — only 2 ATP per glucose. <strong>Oxygen debt:</strong> lactate oxidised later when O<sub>2</sub> available.</p>'},
    {id:'al-bio-t12-l3', title:'Measuring respiration', html:'<h3>Measuring respiration</h3><p><strong>Respirometer:</strong> measures O<sub>2</sub> uptake by a respiring organism (CO<sub>2</sub> absorbed by KOH/soda lime; coloured fluid moves as O<sub>2</sub> is consumed). Rate of O<sub>2</sub> uptake ∝ respiration rate.</p><p>Controls: same mass/temperature; KOH to absorb CO<sub>2</sub> (else pressure unchanged); capillary tube for sensitivity. Compare RQ using CO<sub>2</sub> release vs O<sub>2</sub> uptake.</p><p>Exam reasoning: if the fluid does not move, either no respiration or RQ = 1 without CO<sub>2</sub> absorption — always check the KOH is present.</p>'}
   ],
   quiz:[
    {q:'Net ATP from glycolysis per glucose is', options:['2','4','36','38'], answer:0, explain:'4 made, 2 used → net 2 ATP (+ 2 NADH).'},
    {q:'The link reaction occurs in the', options:['cytoplasm','mitochondrial matrix','cristae','nucleus'], answer:1, explain:'Pyruvate → acetyl CoA in the matrix.'},
    {q:'Oxygen’s role in aerobic respiration is', options:['to oxidise glucose directly','final electron acceptor in oxidative phosphorylation','to make CO<sub>2</sub>','to pump protons'], answer:1, explain:'O<sub>2</sub> accepts electrons + H<sup>+</sup> → water, keeping the chain flowing.'},
    {q:'ATP synthase makes ATP using', options:['electron energy directly','the proton (H<sup>+</sup>) gradient','oxygen','NADH'], answer:1, explain:'Chemiosmosis: H<sup>+</sup> flow through ATP synthase drives phosphorylation.'},
    {q:'RQ for a carbohydrate substrate is', options:['0.7','0.9','1.0','1.5'], answer:2, explain:'C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6O<sub>2</sub> → 6CO<sub>2</sub> + 6H<sub>2</sub>O: 6/6 = 1.0.'},
    {q:'Anaerobic respiration in muscle produces', options:['ethanol','lactate','acetyl CoA','oxygen'], answer:1, explain:'Pyruvate → lactate (regenerates NAD<sup>+</sup>); yeast makes ethanol + CO<sub>2</sub>.'},
    {q:'KOH in a respirometer', options:['provides oxygen','absorbs CO<sub>2</sub>','kills microbes','lubricates'], answer:1, explain:'Removing CO<sub>2</sub> means volume change = O<sub>2</sub> uptake only.'},
    {q:'Cristae are folded to', options:['store DNA','increase surface area for the electron transport chain','hold ribosomes','pump water'], answer:1, explain:'More membrane → more ETC/ATP synthase → more ATP.'},
    {q:'Total ATP per glucose (aerobic, theoretical) is about', options:['2','8','38','100'], answer:2, explain:'2 (glycolysis) + 2 (Krebs) + ~34 (oxidative phosphorylation).'},
    {q:'The oxygen debt is repaid by', options:['breathing faster only','oxidising lactate to pyruvate when O<sub>2</sub> is available','drinking water','resting'], answer:1, explain:'Lactate → pyruvate in the liver (needs ATP/O<sub>2</sub>) after exercise.'}
   ]},
  {id:'al-bio-t13', title:'Photosynthesis (A2)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t13-l1', title:'The light-dependent stage', html:'<h3>The light-dependent stage</h3><p>Location: <strong>thylakoid membranes</strong> (grana). <strong>Photolysis:</strong> light splits water: 2H<sub>2</sub>O → 4H<sup>+</sup> + 4e<sup>−</sup> + O<sub>2</sub>. Electrons pass along the <strong>electron transport chain</strong>, pumping H<sup>+</sup> into the thylakoid space.</p><p><strong>Chemiosmosis</strong> (as in respiration): H<sup>+</sup> gradient drives <strong>ATP synthase</strong> → ATP (<strong>photophosphorylation</strong>). Electrons reduce NADP<sup>+</sup> → <strong>NADPH</strong> (via ferredoxin/NADP reductase).</p><p>Products: ATP, NADPH (to the Calvin cycle), O<sub>2</sub> (waste/byproduct). <strong>Photosystems:</strong> PSI and PSII with reaction centres (P700/P680) and antenna pigments (chlorophyll a/b, carotenoids).</p>'},
    {id:'al-bio-t13-l2', title:'The Calvin cycle', html:'<h3>The Calvin cycle</h3><p>Location: <strong>stroma</strong>. <strong>Carbon fixation:</strong> RuBP (5C) + CO<sub>2</sub> → 2 × GP (3C), catalysed by <strong>RuBisCO</strong> (most abundant enzyme on Earth). <strong>Reduction:</strong> GP → TP (triose phosphate) using ATP + NADPH. <strong>Regeneration:</strong> RuBP rebuilt using ATP.</p><p>Stoichiometry: 6 turns fix 6 CO<sub>2</sub> → 12 TP; 10 TP regenerate 6 RuBP; 2 TP leave → 1 glucose (via further reactions). Overall: 6CO<sub>2</sub> + 12H<sub>2</sub>O → C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6O<sub>2</sub> + 6H<sub>2</sub>O.</p><p><strong>Limiting factors:</strong> light intensity, CO<sub>2</sub> concentration, temperature (enzymes). At high light/CO<sub>2</sub>, temperature (RuBisCO activity) limits.</p>'},
    {id:'al-bio-t13-l3', title:'Investigating photosynthesis', html:'<h3>Investigating photosynthesis</h3><p><strong>Measuring rate:</strong> O<sub>2</sub> evolution from pondweed (gas syringe/burette); CO<sub>2</sub> uptake (pH indicator hydrogencarbonate → purple as CO<sub>2</sub> falls). <strong>Absorption spectrum:</strong> % absorption vs wavelength (peaks in blue/red, trough in green); <strong>action spectrum:</strong> rate vs wavelength — closely matches, proving absorbed light drives photosynthesis.</p><p><strong>Chromatography</strong> separates photosynthetic pigments (chlorophyll a/b, carotenes, xanthophylls) — different R<sub>f</sub> values.</p><p>Greenhouse economics: enriching CO<sub>2</sub> and optimising light/temperature raises yield — but weigh energy costs.</p>'}
   ],
   quiz:[
    {q:'Photolysis is', options:['splitting of glucose','light-driven splitting of water','ATP formation','CO<sub>2</sub> fixation'], answer:1, explain:'2H<sub>2</sub>O → 4H<sup>+</sup> + 4e<sup>−</sup> + O<sub>2</sub> in the thylakoids.'},
    {q:'The light-dependent stage produces', options:['glucose','ATP, NADPH and O<sub>2</sub>','RuBP','CO<sub>2</sub>'], answer:1, explain:'Photophosphorylation → ATP; NADP<sup>+</sup> reduced → NADPH; O<sub>2</sub> from photolysis.'},
    {q:'Carbon fixation is catalysed by', options:['ATP synthase','RuBisCO','DNA polymerase','amylase'], answer:1, explain:'RuBisCO carboxylates RuBP with CO<sub>2</sub>.'},
    {q:'In the Calvin cycle, GP is reduced to TP using', options:['O<sub>2</sub>','ATP and NADPH','water','glucose'], answer:1, explain:'Energy (ATP) + reducing power (NADPH) from the light stage.'},
    {q:'How many Calvin cycle turns to make one glucose?', options:['1','3','6','12'], answer:2, explain:'6 CO<sub>2</sub> fixed → 12 TP; 2 TP net → glucose.'},
    {q:'At very high light intensity and CO<sub>2</sub>, the limiting factor is usually', options:['water','temperature (enzyme activity)','chlorophyll','O<sub>2</sub>'], answer:1, explain:'RuBisCO and other enzymes cap the rate.'},
    {q:'The action spectrum shows', options:['pigment colours','photosynthesis rate vs wavelength','absorption vs pH','leaf area'], answer:1, explain:'Peaks in blue/red match chlorophyll absorption — light absorbed drives the process.'},
    {q:'Chromatography of leaf pigments separates them by', options:['mass','solubility/affinity (R<sub>f</sub>)','charge','size'], answer:1, explain:'Different partition between solvent and paper → different R<sub>f</sub>.'},
    {q:'Hydrogencarbonate indicator turns purple when', options:['CO<sub>2</sub> rises','CO<sub>2</sub> falls (photosynthesis)','O<sub>2</sub> rises','pH falls'], answer:1, explain:'Less CO<sub>2</sub> → less carbonic acid → more alkaline → purple.'},
    {q:'Cyclic photophosphorylation produces', options:['NADPH only','ATP only (no NADPH/O<sub>2</sub>)','glucose','CO<sub>2</sub>'], answer:1, explain:'Electrons cycle around PSI: proton gradient → ATP, no NADPH or photolysis.'}
   ]},
  {id:'al-bio-t14', title:'Homeostasis (A2)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t14-l1', title:'Principles of homeostasis', html:'<h3>Principles of homeostasis</h3><p><strong>Homeostasis:</strong> maintaining a constant internal environment. Controlled by <strong>negative feedback</strong>: a rise above the set point triggers responses that lower it (and vice versa). Components: <strong>receptor</strong> (detects), <strong>coordinator</strong> (CNS/endocrine), <strong>effector</strong> (muscle/gland).</p><p>Regulated variables: blood glucose, body temperature, water potential/blood water, CO<sub>2</sub>/pH, ions.</p><p><strong>Positive feedback</strong> amplifies change (e.g. oxytocin in childbirth, blood clotting) — rare in homeostasis.</p>'},
    {id:'al-bio-t14-l2', title:'Blood glucose regulation', html:'<h3>Blood glucose regulation</h3><p><strong>Pancreas:</strong> <strong>β cells</strong> secrete <strong>insulin</strong> (high glucose → liver/muscle take up glucose, convert to glycogen; cells increase respiration); <strong>α cells</strong> secrete <strong>glucagon</strong> (low glucose → glycogenolysis/gluconeogenesis in liver).</p><p><strong>Diabetes:</strong> Type 1 — autoimmune destruction of β cells (no insulin; treat with injections); Type 2 — insulin resistance/reduced secretion (linked to obesity; treat with diet, exercise, drugs). Symptoms: high blood glucose, glucose in urine, thirst, fatigue.</p><p>Second messenger model (glucagon/adrenaline): hormone → receptor → adenyl cyclase → <strong>cAMP</strong> → enzyme cascade → glycogen breakdown. Amplification: one hormone → many cAMP → huge response.</p>'},
    {id:'al-bio-t14-l3', title:'Temperature regulation and the kidney', html:'<h3>Temperature regulation and the kidney</h3><p><strong>Thermoregulation:</strong> hypothalamus (receptors) → responses to cold: vasoconstriction, shivering, piloerection, more adrenaline/thyroxine; to heat: vasodilation, sweating, less metabolic heat. <strong>Ectotherms</strong> rely on behaviour; <strong>endotherms</strong> on physiology (costly).</p><p><strong>Osmoregulation:</strong> hypothalamus osmoreceptors → posterior pituitary releases <strong>ADH</strong> when blood water low → collecting duct more permeable → more water reabsorbed → concentrated urine. Negative feedback.</p><p><strong>Kidney:</strong> ultrafiltration at glomerulus (high pressure, small molecules forced out); selective reabsorption in proximal convoluted tubule (all glucose, most water/ions); loop of Henle builds medulla gradient; ADH acts on collecting duct.</p>'}
   ],
   quiz:[
    {q:'Negative feedback', options:['amplifies change','reverses change back towards the set point','stops all responses','needs no receptor'], answer:1, explain:'Corrective responses oppose the initial deviation.'},
    {q:'Insulin is secreted by', options:['α cells','β cells','the liver','the adrenal gland'], answer:1, explain:'Pancreatic β cells respond to high blood glucose.'},
    {q:'Glucagon causes', options:['glycogenesis','glycogenolysis in the liver','glucose uptake by muscle','insulin release'], answer:1, explain:'Low glucose → glucagon → liver breaks down glycogen.'},
    {q:'Type 1 diabetes is', options:['insulin resistance','autoimmune destruction of β cells','caused by sugar intake','curable by diet'], answer:1, explain:'No insulin produced: needs exogenous insulin.'},
    {q:'In the second messenger model, cAMP', options:['is the hormone','amplifies the signal inside the cell','binds DNA','leaves the cell'], answer:1, explain:'One receptor → many cAMP → enzyme cascade: massive amplification.'},
    {q:'In the cold, the body responds with', options:['vasodilation','vasoconstriction and shivering','sweating','panting'], answer:1, explain:'Conserve heat (less skin blood flow) + generate heat (muscle contraction).'},
    {q:'ADH increases', options:['urine volume','water reabsorption in the collecting duct','blood pressure directly','glucose uptake'], answer:1, explain:'ADH → aquaporins inserted → more water reabsorbed → concentrated urine.'},
    {q:'Ultrafiltration occurs at the', options:['proximal tubule','glomerulus/Bowman’s capsule','loop of Henle','collecting duct'], answer:1, explain:'High-pressure filtration of small molecules from blood.'},
    {q:'All glucose is reabsorbed in the', options:['loop of Henle','proximal convoluted tubule','distal tubule','collecting duct'], answer:1, explain:'Selective reabsorption: glucose, amino acids, most ions/water.'},
    {q:'An ectotherm regulates temperature mainly by', options:['sweating','behaviour (e.g. basking)','shivering','fur'], answer:1, explain:'Ectotherms gain/lose heat behaviourally; endotherms physiologically.'}
   ]},
  {id:'al-bio-t15', title:'Control and coordination (A2)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t15-l1', title:'The nervous system and neurones', html:'<h3>The nervous system and neurones</h3><p><strong>Neurones:</strong> sensory (receptor → CNS), relay (CNS), motor (CNS → effector). Structure: dendrites, cell body, axon (myelin sheath + Schwann cells, nodes of Ranvier), synaptic knobs.</p><p><strong>Resting potential</strong> (−70 mV): Na<sup>+</sup>/K<sup>+</sup> pump (3 Na<sup>+</sup> out, 2 K<sup>+</sup> in) + K<sup>+</sup> leakage → inside negative. <strong>Action potential:</strong> stimulus → Na<sup>+</sup> channels open → depolarisation (+40 mV) → Na<sup>+</sup> channels close, K<sup>+</sup> open → repolarisation → hyperpolarisation → resting restored. <strong>All-or-nothing;</strong> refractory period limits frequency.</p><p><strong>Myelin</strong> → saltatory conduction (jumps node to node) — faster and energy-efficient. Larger diameter also faster.</p>'},
    {id:'al-bio-t15-l2', title:'Synapses', html:'<h3>Synapses</h3><p><strong>Synapse:</strong> junction between neurones. Action potential → Ca<sup>2+</sup> channels open → vesicles release <strong>acetylcholine</strong> → diffuses across cleft → binds receptors on postsynaptic membrane → Na<sup>+</sup> influx → new action potential (if threshold reached). <strong>Acetylcholinesterase</strong> breaks down ACh (→ ethanoic acid + choline, recycled).</p><p>Features: <strong>unidirectional</strong>; <strong>summation</strong> (temporal/spatial); <strong>inhibition</strong> (IPSPs); drugs/poisons act here (e.g. organophosphates inhibit acetylcholinesterase).</p><p><strong>Neuromuscular junction</strong> works similarly, triggering muscle contraction.</p>'},
    {id:'al-bio-t15-l3', title:'Plant growth regulators', html:'<h3>Plant growth regulators</h3><p><strong>Auxin (IAA):</strong> made in shoot tips; <strong>phototropism</strong> — auxin moves to the shaded side → cell elongation there → shoot bends towards light. <strong>Gravitropism:</strong> auxin accumulates lower side — shoots bend up (stimulates elongation), roots bend down (high auxin <strong>inhibits</strong> root elongation).</p><p><strong>Gibberellins:</strong> stem elongation, seed germination (trigger amylase in barley — brewing), break dormancy. <strong>ABA:</strong> closes stomata in drought, maintains dormancy. <strong>Ethene:</strong> fruit ripening.</p><p>Investigating: coleoptile tips removed/covered (Darwin’s experiments) prove the tip senses light and sends a chemical signal.</p>'}
   ],
   quiz:[
    {q:'The resting potential of a neurone is about', options:['+40 mV','−70 mV','0 mV','−700 mV'], answer:1, explain:'Na<sup>+</sup>/K<sup>+</sup> pump + K<sup>+</sup> leak: inside negative at −70 mV.'},
    {q:'Depolarisation is caused by', options:['K<sup>+</sup> leaving','Na<sup>+</sup> rushing in','Cl<sup>−</sup> entering','pumps stopping'], answer:1, explain:'Voltage-gated Na<sup>+</sup> channels open: Na<sup>+</sup> influx → +40 mV.'},
    {q:'Saltatory conduction', options:['is slower','jumps between nodes of Ranvier — faster','needs no myelin','occurs in muscles'], answer:1, explain:'Myelinated axons: action potentials regenerate only at nodes.'},
    {q:'At a cholinergic synapse, the neurotransmitter is', options:['dopamine','acetylcholine','serotonin','GABA'], answer:1, explain:'ACh released from vesicles; broken down by acetylcholinesterase.'},
    {q:'Acetylcholinesterase', options:['makes ACh','breaks down ACh in the cleft','blocks receptors','pumps Ca<sup>2+</sup>'], answer:1, explain:'Hydrolyses ACh so the synapse resets for the next impulse.'},
    {q:'Synapses ensure impulses travel', options:['faster','in one direction','without ATP','in loops'], answer:1, explain:'Vesicles/receptors on one side only: unidirectional.'},
    {q:'Phototropism in shoots is caused by', options:['auxin on the lit side','auxin accumulating on the shaded side → elongation there','gravity','cell division'], answer:1, explain:'Unequal auxin → unequal elongation → bending towards light.'},
    {q:'High auxin concentration in roots', options:['stimulates elongation','inhibits elongation','has no effect','kills cells'], answer:1, explain:'Roots are more sensitive: high auxin inhibits, so the lower side grows less → root bends down.'},
    {q:'Gibberellins promote', options:['leaf fall','stem elongation and seed germination','dormancy','fruit ripening'], answer:1, explain:'GA stimulates internode growth and amylase production in germinating seeds.'},
    {q:'During drought, stomata close in response to', options:['auxin','abscisic acid (ABA)','gibberellin','ethene'], answer:1, explain:'ABA from roots/leaves triggers guard-cell closure, conserving water.'}
   ]},
  {id:'al-bio-t16', title:'Inheritance (A2)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t16-l1', title:'Meiosis and genetic variation', html:'<h3>Meiosis and genetic variation</h3><p><strong>Meiosis:</strong> two divisions → 4 haploid genetically different gametes. <strong>Prophase I:</strong> homologous chromosomes pair; <strong>crossing over</strong> swaps segments. <strong>Metaphase I:</strong> homologous pairs align (independent assortment). <strong>Anaphase I:</strong> homologues separate (reduction division). Meiosis II separates chromatids (like mitosis).</p><p>Sources of variation: <strong>crossing over</strong>, <strong>independent assortment</strong>, <strong>random fertilisation</strong>, mutation.</p><p><strong>Chiasmata</strong> (X-shaped) mark crossover points. Genetic maps use crossover frequency: 1% recombination = 1 map unit.</p>'},
    {id:'al-bio-t16-l2', title:'Mendelian genetics and dihybrid crosses', html:'<h3>Mendelian genetics and dihybrid crosses</h3><p>Terms: <strong>gene</strong> (DNA section coding a polypeptide), <strong>allele</strong> (variant), <strong>genotype</strong> (alleles), <strong>phenotype</strong> (expressed traits), <strong>homozygous/heterozygous</strong>, <strong>dominant/recessive</strong>, <strong>locus</strong>.</p><p><strong>Monohybrid:</strong> Aa × Aa → 3:1 phenotypic ratio. <strong>Test cross:</strong> unknown × homozygous recessive reveals genotype. <strong>Dihybrid:</strong> AaBb × AaBb → 9:3:3:1 (independent assortment).</p><p><strong>Chi-squared test:</strong> χ² = Σ((O−E)²/E); compare with critical value (degrees of freedom = categories − 1) at p = 0.05. If χ² < critical, deviation is not significant — accept the predicted ratio.</p>'},
    {id:'al-bio-t16-l3', title:'Beyond Mendel: linkage, sex and codominance', html:'<h3>Beyond Mendel: linkage, sex and codominance</h3><p><strong>Linked genes</strong> (same chromosome) do not assort independently — parental combinations predominate; <strong>recombinants</strong> arise from crossing over. <strong>Sex linkage:</strong> genes on X (e.g. haemophilia, red-green colour blindness — recessive, more common in males who are hemizygous).</p><p><strong>Codominance:</strong> both alleles expressed (AB blood group; roan cattle). <strong>Multiple alleles:</strong> ABO blood (I<sup>A</sup>, I<sup>B</sup>, i). <strong>Epistasis:</strong> one gene masks another (e.g. 9:7 or 12:3:1 ratios). <strong>Polygenic:</strong> many genes → continuous variation (height, skin colour).</p><p><strong>Autosomes</strong> vs sex chromosomes; <strong>pedigree analysis</strong> deduces inheritance patterns.</p>'}
   ],
   quiz:[
    {q:'Crossing over occurs in', options:['prophase of mitosis','prophase I of meiosis','metaphase II','anaphase I'], answer:1, explain:'Homologous chromosomes pair and exchange segments in prophase I.'},
    {q:'Independent assortment happens at', options:['metaphase of mitosis','metaphase I','prophase II','telophase I'], answer:1, explain:'Random alignment of homologous pairs on the metaphase I plate.'},
    {q:'Aa × Aa monohybrid phenotypic ratio', options:['1:1','3:1','9:3:3:1','1:2:1'], answer:1, explain:'Genotypes 1AA:2Aa:1aa → phenotypes 3 dominant : 1 recessive.'},
    {q:'A test cross uses', options:['two heterozygotes','homozygous recessive partner','two dominants','self-pollination'], answer:1, explain:'aa × unknown: offspring phenotypes reveal the unknown genotype.'},
    {q:'Dihybrid AaBb × AaBb phenotypic ratio', options:['3:1','1:1:1:1','9:3:3:1','1:2:1'], answer:2, explain:'Independent assortment of two genes: classic 9:3:3:1.'},
    {q:'In a chi-squared test, χ² less than the critical value means', options:['reject the hypothesis','accept the hypothesis (deviation not significant)','redo the cross','p < 0.05'], answer:1, explain:'Deviation from expected can be attributed to chance.'},
    {q:'Red-green colour blindness is more common in males because', options:['males have two X chromosomes','the gene is X-linked recessive; males are hemizygous','it is dominant','females are immune'], answer:1, explain:'One X in males: a single recessive allele is expressed.'},
    {q:'AB blood group is an example of', options:['complete dominance','codominance','epistasis','linkage'], answer:1, explain:'Both I<sup>A</sup> and I<sup>B</sup> are expressed.'},
    {q:'Linked genes', options:['assort independently','are on the same chromosome — parental combos predominate','are always sex-linked','cannot cross over'], answer:1, explain:'Linked loci travel together unless crossing over separates them.'},
    {q:'Continuous variation (e.g. height) indicates', options:['one gene','polygenic inheritance','sex linkage','mutation'], answer:1, explain:'Many genes + environment → smooth bell-curve distribution.'}
   ]},
  {id:'al-bio-t17', title:'Selection and evolution (A2)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t17-l1', title:'Natural selection', html:'<h3>Natural selection</h3><p><strong>Natural selection:</strong> (1) variation exists (mutation, meiosis); (2) overproduction → competition; (3) <strong>selection pressure</strong> (predation, disease, climate); (4) best-adapted survive and reproduce (<strong>survival of the fittest</strong>); (5) advantageous alleles passed on → allele frequency changes.</p><p>Examples: <strong>industrial melanism</strong> (peppered moths — dark form camouflaged on soot); <strong>antibiotic resistance</strong> in bacteria; pesticide resistance in insects.</p><p><strong>Directional</strong> (one extreme favoured), <strong>stabilising</strong> (average favoured, e.g. human birth weight), <strong>disruptive</strong> (both extremes favoured) selection.</p>'},
    {id:'al-bio-t17-l2', title:'Speciation', html:'<h3>Speciation</h3><p><strong>Species:</strong> group of similar organisms that can interbreed to produce fertile offspring. <strong>Speciation:</strong> formation of new species.</p><p><strong>Allopatric:</strong> geographical barrier → isolated populations → different selection pressures/mutations → genetic divergence → <strong>reproductive isolation</strong> (cannot interbreed even if reunited). <strong>Sympatric:</strong> no barrier — e.g. polyploidy in plants, niche separation.</p><p>Reproductive isolating mechanisms: seasonal, behavioural, mechanical, gametic, hybrid infertility/sterility.</p>'},
    {id:'al-bio-t17-l3', title:'Evidence for evolution', html:'<h3>Evidence for evolution</h3><p><strong>Fossils:</strong> transitional forms (Archaeopteryx — reptile/bird); fossil record shows succession. <strong>Comparative anatomy:</strong> homologous structures (pentadactyl limb — common ancestor) vs analogous (wings of insects/birds — convergent evolution).</p><p><strong>DNA/protein comparisons:</strong> more similar sequences → more closely related (molecular clock). <strong>Biogeography:</strong> distribution matches continental drift. <strong>Selective breeding</strong> shows selection can reshape species rapidly.</p><p><strong>Artificial selection:</strong> humans select desired traits (dairy cattle, wheat) — parallels natural selection but with human goals; reduces genetic diversity.</p>'}
   ],
   quiz:[
    {q:'Natural selection requires', options:['mutation only','variation, competition, selection, inheritance','a barrier','human choice'], answer:1, explain:'Variation → differential survival → heredity shifts allele frequencies.'},
    {q:'Industrial melanism in peppered moths shows', options:['mutation creating wings','selection by predation favouring camouflaged forms','migration','genetic drift'], answer:1, explain:'Dark moths survived better on soot-darkened trees; light form returned with clean air.'},
    {q:'Stabilising selection', options:['favours one extreme','favours the average, selecting against extremes','favours both extremes','has no effect'], answer:1, explain:'E.g. human birth weight: very small/large babies less likely to survive.'},
    {q:'Allopatric speciation needs', options:['polyploidy','a geographical barrier isolating populations','human breeding','a mutation only'], answer:1, explain:'Isolation → independent evolution → reproductive isolation.'},
    {q:'Two populations are different species when', options:['they look different','they cannot interbreed to produce fertile offspring','they live apart','they eat differently'], answer:1, explain:'Biological species concept: reproductive isolation.'},
    {q:'The pentadactyl limb is evidence of', options:['convergent evolution','common ancestry (homologous structures)','design','mutation'], answer:1, explain:'Same bone pattern in whale, bat, human → inherited from a common ancestor.'},
    {q:'Analogous structures (e.g. insect and bird wings) show', options:['common ancestry','convergent evolution','homology','speciation'], answer:1, explain:'Similar function, different origin: independent adaptation to flight.'},
    {q:'DNA sequence comparison is powerful because', options:['DNA never changes','similarity reflects relatedness (molecular clock)','it is cheap','fossils are absent'], answer:1, explain:'Fewer differences = more recent common ancestor.'},
    {q:'Artificial selection differs from natural in', options:['speed','the selector is human with specific goals','mechanism','inheritance'], answer:1, explain:'Same principles (variation + selection + heredity), human-chosen criteria.'},
    {q:'Antibiotic resistance is an example of', options:['Lamarckism','directional natural selection','stabilising selection','genetic drift'], answer:1, explain:'Antibiotics select resistant mutants: allele frequencies shift directionally.'}
   ]},
  {id:'al-bio-t18', title:'Classification, biodiversity and conservation (A2)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t18-l1', title:'Classification', html:'<h3>Classification</h3><p><strong>Taxonomy hierarchy:</strong> domain → kingdom → phylum → class → order → family → genus → species. <strong>Binomial nomenclature:</strong> Genus species (italicised, e.g. <em>Homo sapiens</em>).</p><p><strong>Three domains:</strong> Archaea, Bacteria, Eukarya. <strong>Five kingdoms:</strong> Prokaryotae, Protoctista, Fungi, Plantae, Animalia.</p><p>Modern classification uses <strong>DNA/protein sequence</strong> data (phylogenetics) — more objective than morphology; has reclassified many groups.</p>'},
    {id:'al-bio-t18-l2', title:'Biodiversity', html:'<h3>Biodiversity</h3><p><strong>Biodiversity:</strong> variety of life — genetic, species, habitat/ecosystem diversity. Measured by <strong>species richness</strong> (count) and <strong>evenness</strong>; <strong>Simpson’s index D = 1 − Σ(n/N)²</strong> combines both (higher D = more diverse).</p><p>Worked example: community A: 10,10,10,10 (N=40): D = 1 − 4(0.25²) = 0.75. Community B: 37,1,1,1: D = 1 − (0.925² + 3×0.025²) ≈ 0.14. A is far more diverse despite equal richness.</p><p>Threats: habitat destruction, pollution, climate change, overexploitation, invasive species. Sampling: random quadrats, transects, mark–release–recapture (Lincoln index: N = n<sub>1</sub>×n<sub>2</sub>/m<sub>2</sub>).</p>'},
    {id:'al-bio-t18-l3', title:'Conservation', html:'<h3>Conservation</h3><p>Reasons: <strong>ethical</strong> (intrinsic value), <strong>economic</strong> (resources, ecotourism, medicines), <strong>ecological</strong> (ecosystem services, stability), <strong>aesthetic/cultural</strong>.</p><p><strong>In situ:</strong> protect in natural habitat — national parks, marine reserves, wildlife corridors. <strong>Ex situ:</strong> zoos, botanical gardens, <strong>seed banks</strong> (e.g. Millennium Seed Bank), captive breeding + reintroduction.</p><p><strong>Sustainable management:</strong> managed forestry, fishing quotas, CITES (controls trade in endangered species). Conservation needs local community involvement to succeed.</p>'}
   ],
   quiz:[
    {q:'The correct taxonomic order (largest to smallest) is', options:['kingdom, phylum, class, order, family, genus, species','species, genus, family, order, class, phylum, kingdom','domain, species, genus','phylum, kingdom, class'], answer:0, explain:'Domain → kingdom → phylum → class → order → family → genus → species.'},
    {q:'Binomial nomenclature means', options:['two kingdoms','Genus species naming','two domains','common names'], answer:1, explain:'E.g. Homo sapiens: genus capitalised, species lowercase, italicised.'},
    {q:'The three domains are', options:['plants, animals, fungi','Archaea, Bacteria, Eukarya','prokaryotes, eukaryotes, viruses','land, sea, air'], answer:1, explain:'Woese’s three-domain system based on rRNA sequences.'},
    {q:'Simpson’s index measures', options:['richness only','diversity combining richness and evenness','population size','biomass'], answer:1, explain:'D = 1 − Σ(n/N)²: accounts for both species count and abundance balance.'},
    {q:'A community with high evenness has', options:['one dominant species','abundances spread across species','few species','low diversity'], answer:1, explain:'Evenness: individuals distributed evenly among species.'},
    {q:'Mark–release–recapture estimates', options:['biodiversity','population size (Lincoln index)','growth rate','mortality'], answer:1, explain:'N = (marked₁ × caught₂)/recaptured: assumes mixing and no births/deaths.'},
    {q:'Seed banks are an example of', options:['in situ conservation','ex situ conservation','sustainable fishing','reintroduction'], answer:1, explain:'Ex situ: preserving genetic diversity outside natural habitats.'},
    {q:'CITES aims to', options:['ban all hunting','control international trade in endangered species','fund zoos','plant trees'], answer:1, explain:'Convention on International Trade in Endangered Species.'},
    {q:'An ecological reason for conservation is', options:['beauty','ecosystem services and stability','profit','tradition'], answer:1, explain:'Biodiverse ecosystems are more resilient and provide services (pollination, water purification).'},
    {q:'Modern phylogenetics mainly uses', options:['fossils only','DNA/protein sequence data','behaviour','habitat'], answer:1, explain:'Molecular sequences give objective measures of relatedness.'}
   ]},
  {id:'al-bio-t19', title:'Genetic technology (A2)', urdu:'', comingSoon:false,
   lessons:[
    {id:'al-bio-t19-l1', title:'Genetic engineering', html:'<h3>Genetic engineering</h3><p><strong>Recombinant DNA:</strong> (1) isolate gene (e.g. human insulin gene); (2) cut <strong>plasmid</strong> vector and gene with the same <strong>restriction endonuclease</strong> → sticky ends; (3) join with <strong>DNA ligase</strong>; (4) insert into bacteria (<strong>transformation</strong> — heat shock/electroporation); (5) select using <strong>antibiotic resistance marker genes</strong>; (6) culture in fermenters → harvest product.</p><p><strong>Insulin:</strong> produced by GM <em>E. coli</em>/yeast — purer and more reliable than animal insulin. <strong>Golden rice:</strong> engineered to make vitamin A precursor (combats deficiency).</p><p><strong>PCR:</strong> amplifies DNA — denature (95 °C), anneal primers (55 °C), extend with Taq polymerase (72 °C); cycles double DNA each round: 2<sup>n</sup> copies.</p>'},
    {id:'al-bio-t19-l2', title:'Gene therapy and GM crops', html:'<h3>Gene therapy and GM crops</h3><p><strong>Gene therapy:</strong> inserting functional alleles to treat genetic disorders — e.g. SCID (“bubble boy” disease): patient’s bone marrow cells given a working gene via a viral vector, then returned. <strong>Somatic</strong> therapy affects only the patient (not inherited); <strong>germ-line</strong> therapy would be inherited (banned/ethically fraught).</p><p><strong>GM crops:</strong> Bt cotton/maize (bacterial toxin kills pests — less insecticide), herbicide-resistant soya, golden rice. Benefits: yield, reduced pesticide, nutrition. Concerns: gene flow to wild relatives, pest resistance evolution, corporate control, labelling.</p><p><strong>Electrophoresis + Southern blotting</strong> detect specific DNA sequences (e.g. for diagnosis).</p>'},
    {id:'al-bio-t19-l3', title:'Ethics and social implications', html:'<h3>Ethics and social implications</h3><p>Debates: <strong>safety</strong> (long-term effects of GM foods), <strong>environment</strong> (biodiversity, superweeds), <strong>ownership</strong> (patents on genes/seeds), <strong>designer babies</strong> (germ-line editing — CRISPR), <strong>animal welfare</strong> (transgenic animals), <strong>access/equity</strong> (who benefits?).</p><p>Regulation: risk assessment, field-trial controls, labelling laws, international agreements (Cartagena Protocol on biosafety).</p><p>Exam reasoning: present balanced arguments with specific examples; distinguish scientific evidence from ethical values; note that “natural” ≠ safe and “GM” ≠ unsafe — assess case by case.</p>'}
   ],
   quiz:[
    {q:'Restriction endonucleases', options:['join DNA','cut DNA at specific sequences','copy DNA','unwind DNA'], answer:1, explain:'Molecular scissors: recognise palindromic sequences, often leaving sticky ends.'},
    {q:'DNA ligase', options:['cuts plasmids','joins DNA fragments (phosphodiester bonds)','amplifies DNA','selects bacteria'], answer:1, explain:'Seals nicks: joins the insert to the plasmid vector.'},
    {q:'Marker genes in plasmids allow', options:['faster growth','selection of transformed bacteria (antibiotic resistance)','bigger plasmids','gene expression'], answer:1, explain:'Only bacteria taking up the plasmid survive the antibiotic.'},
    {q:'Human insulin is now made by', options:['pigs','GM bacteria/yeast','chemical synthesis','plants'], answer:1, explain:'Recombinant E. coli/yeast: identical human insulin, unlimited supply.'},
    {q:'One PCR cycle consists of', options:['cut, join, select','denature, anneal primers, extend','transcribe, translate','lyse, spin, blot'], answer:1, explain:'95 °C separate strands; ~55 °C primers bind; 72 °C Taq extends.'},
    {q:'After 20 PCR cycles, one DNA molecule becomes about', options:['20','400','1,048,576 (2<sup>20</sup>)','40'], answer:2, explain:'Exponential: 2<sup>n</sup> copies.'},
    {q:'Somatic gene therapy', options:['is inherited','affects only the treated patient','changes gametes','is banned everywhere'], answer:1, explain:'Modified somatic cells are not passed to offspring.'},
    {q:'Bt crops are engineered to', options:['resist herbicides','produce a bacterial insect toxin','grow faster','tolerate drought'], answer:1, explain:'Cry toxin from Bacillus thuringiensis kills insect pests.'},
    {q:'Golden rice addresses', options:['yield','vitamin A deficiency','drought','salinity'], answer:1, explain:'Engineered β-carotene pathway: provitamin A in the grain.'},
    {q:'A major ethical concern about germ-line editing is', options:['cost only','changes are inherited by future generations','it never works','it is too slow'], answer:1, explain:'Heritable edits affect descendants who cannot consent; off-target risks.'}
   ]}
]});
